// RQ-03: quem pode excluir um pedido. ADMIN: sempre. GERENTE: somente pedido ABERTO. OPERADOR e visitante (null): nunca.
export function podeExcluir(usuario, pedido) {
  if (!usuario) return false;
  if (usuario.perfil === 'ADMIN') return true;
  if (usuario.perfil === 'GERENTE') return pedido.status === 'ABERTO';
  return false;
}

// RQ-06: o cupom PRUMO10 concede 10% de desconto sobre o total. Qualquer outro código não altera o total.
export function aplicarCupom(codigo, total) {
  if (total < 0) throw new RangeError('total negativo');
  return codigo === 'PRUMO10' ? Math.round(total * 0.9 * 100) / 100 : total;
}

// RQ-01: elegibilidade por idade. Intervalo fechado: 18 a 65 anos, inteiros.
export function elegivel(idade) {
  if (!Number.isInteger(idade)) throw new TypeError('idade deve ser um inteiro');
  return idade >= 18 && idade <= 65;
}

import { writeFileSync } from 'node:fs';
import { total } from './total-a.mjs';
import { total as totalAlternativo } from './total-b.mjs';
export async function relatorio(itens, rota = 'principal') {
  const modulo = await import('./' + 'formatacao' + '.mjs');
  const soma = rota === 'principal' ? total(itens) : totalAlternativo(itens);
  return { estado: 'NOVO', total: soma, texto: modulo.formatar(soma) };
}
export async function gerarEGravar(itens, arquivo) {
  if (!Array.isArray(itens)) throw new TypeError('Itens inválidos');
  const resultado = await relatorio(itens);
  writeFileSync(arquivo, JSON.stringify(resultado));
  return resultado;
}

// RQ-02: o frete depende da região. SUL e SUDESTE: 10; NORDESTE e NORTE: 20; CENTRO_OESTE: 15.
const tabela = { SUL: 10, SUDESTE: 10, NORDESTE: 20, NORTE: 20, CENTRO_OESTE: 15 };
export function frete(regiao) {
  if (!Object.hasOwn(tabela, regiao)) throw new RangeError('região desconhecida');
  return tabela[regiao];
}

import { podeExcluir } from './acesso.mjs';

// RQ-04: uma exclusão recusada não pode alterar nenhum dado existente.
export function criarLoja(pedidosIniciais = []) {
  const pedidos = new Map(pedidosIniciais.map((p) => [p.id, { ...p }]));
  return {
    obter: (id) => (pedidos.has(id) ? { ...pedidos.get(id) } : undefined),
    total: () => pedidos.size,
    excluir(id, usuario) {
      const pedido = pedidos.get(id);
      if (!pedido) throw new Error('pedido inexistente');
      if (!podeExcluir(usuario, pedido)) throw new Error('exclusão não autorizada');
      pedidos.delete(id);
    }
  };
}

